// C++11 style: template struct with a nested ::type
#include <type_traits>

typename std::remove_const<const int>::type var1; // yields int
typename std::add_lvalue_reference<decltype(var1)>::type var2 = var1; // yields int&

// C++14 style: alias templates with _t suffix (cleaner)
#include <type_traits>

std::remove_const_t<const int> var3; // yields int
std::add_lvalue_reference_t<decltype(var3)> var4 = var3; // yields int&

// C++14-style alias can be implemented in C++11
template <class T>
using my_remove_const_t = typename std::remove_const<T>::type;
